function errorsText(errors,map){const labels={fairness:'余分な公休の偏り',coverage:'必要人数の不足',night_coverage:'夜勤人数',sunday_limit:'日曜の人数緩和の日数超過',request:'希望休への出勤',shift_request:'希望勤務と異なる勤務',locked:'固定した勤務の変更',days_off:'公休不足',consecutive:'連勤上限',consecutive_plus_one:'連勤＋1の回数',night_link:'夜勤と明けのつながり',night_rest:'明けの翌日は公休',night_eligibility:'夜勤できない日の勤務',day_shift_eligibility:'日勤の種類の違反',eligibility:'勤務形態',overtime_eligibility:'A残の可否',adjacent_overtime:'連日のA残',overtime_limit:'A残の回数',weekly:'週の出勤上限',structure:'未入力または不明な勤務'};return errors.slice(0,8).map(e=>{const name=data.staff.find(s=>s.id===map[e.staff])?.name;if(e.code==='night_coverage'&&Number.isInteger(e.actual))return `${dateLabel(e.day)} 夜勤：${e.actual}人／必要1人${e.actual===0?'（未配置・1人不足）':'（人数超過）'}`;if(e.code==='coverage'&&Number.isInteger(e.required)&&Number.isInteger(e.actual)){const time={420:'朝7:00',600:'昼10:00',1065:'夕17:45'}[e.time]||'';return `${e.day?dateLabel(e.day):''} ${time}：${e.actual}人／必要${e.required}人（${e.required-e.actual}人不足）`;}if(e.code==='day_shift_eligibility')return [name,e.day?dateLabel(e.day):'',`${DAYTYPE[e.allowed]||'日勤の種類'}の設定ですが、「${LONG[e.actual]||e.actual}」が入っています`].filter(Boolean).join('：');if(e.code==='shift_request')return [name,e.day?dateLabel(e.day):'',`希望は「${LONG[e.requested]||e.requested}」ですが、表は「${LONG[e.actual]||e.actual}」です`].filter(Boolean).join('：');if(e.code==='sunday_limit'&&Number.isInteger(e.actual))return `日曜の人数緩和が${e.actual}日あります（設定は${e.required}日まで）。`;return [name,e.day?dateLabel(e.day):'',labels[e.code]||e.detail||String(e)].filter(Boolean).join('：');}).join('／')+(errors.length>8?` ほか${errors.length-8}件`:'');}
