if(run.stale||!current())return;
const r=run.best||run.last;
if(run.best){s.assignments=fromRemote(r.assignments,payload.map);const {assignments,carryForward,...meta}=r;s.workSignature=payload.signature;s.meta={...meta,seconds:run.seconds,timing:{...r.timing,mode:'complete',maxSeconds:120},workflow:{rounds:run.rounds,automaticExtended:run.rounds.length>1},signature:payload.signature,tableSignature:JSON.stringify(s.assignments)};if(run.error)state.error='追加計算を完了できなかったため、確認済みの表を表示しています。';}
